package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func solution(a, b int) int {
	i := 0
	for a <= b {
		a *= 3
		b *= 2
		i++
	}
	return i
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		line := scanner.Text()
		parts := strings.Fields(line)
		if len(parts) >= 2 {
			a, _ := strconv.Atoi(parts[0])
			b, _ := strconv.Atoi(parts[1])
			result := solution(a, b)
			fmt.Println(result)
		}
	}
}

